/* Border beam: a conic gradient rotates behind a mask that keeps only the 1px edge. */
@property --border-beam-angle { syntax: '<angle>'; inherits: false; initial-value: 0deg; }
.border-beam { position: relative; border: 1px solid var(--rule); }
.border-beam-light { position: absolute; inset: -1px; border: 1px solid transparent; pointer-events: none; background: conic-gradient(from var(--border-beam-angle), transparent 0 75%, var(--accent) 100%) border-box; -webkit-mask: linear-gradient(var(--foreground) 0 0) padding-box, linear-gradient(var(--foreground) 0 0); -webkit-mask-composite: xor; mask: linear-gradient(var(--foreground) 0 0) padding-box exclude, linear-gradient(var(--foreground) 0 0); animation: border-beam-spin var(--border-beam-duration, 6s) linear infinite; }
@keyframes border-beam-spin { to { --border-beam-angle: 360deg; } }
@media (prefers-reduced-motion: reduce) { .border-beam-light { display: none; } }

source.content:
import {forwardRef, type CSSProperties, type HTMLAttributes} from 'react';
import {cx} from '../../utils/cx';

export interface BorderBeamProps extends HTMLAttributes<HTMLDivElement> {
  /** Seconds for the light to travel once around. Default 6. */
  duration?: number;
}

/** A box with a thin rule and a light that travels around it. CSS only; the beam is decorative and off for reduced motion. */
export const BorderBeam = forwardRef<HTMLDivElement, BorderBeamProps>(function BorderBeam({duration = 6, className, style, children, ...rest}, ref) {
  return (
    <div ref={ref} className={cx('border-beam', className)} style={{'--border-beam-duration': `${duration}s`, ...style} as CSSProperties} {...rest}>
      <span className="border-beam-light" aria-hidden="true" />
      {children}
    </div>
  );
});
